#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int d) : data(d), next(nullptr) {}
};

void printBackward(Node* node) {
    if (node == nullptr) {
        return;
    }
    printBackward(node->next);
    cout << node->data << " ";
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    printBackward(head);
    cout << endl;
    freeList(head);
    return 0;
}
